function Page_TutorialsGuide(params){const _root=document.createDocumentFragment();const _e6218=WF.el("div",{className:"wf-stack wf-gap--lg"});const _e6219=WF.el("div",{className:"wf-markdown",markdown:"These three tutorials each build a whole project, step by step, and each project is complete in the repository under `examples/tutorials/`. None needs a server: what a project keeps, it keeps in the reader's browser. Each tutorial stands on its own, so pick the one that matches where you are, or do them in order."});_e6218.appendChild(_e6219);const _e6220=WF.el("table",{className:"wf-table"},WF.el("caption",{className:"wf-visually-hidden"},"Tutorials"));const _e6221=WF.el("thead",{});const _e6222=WF.el("tr",{});const _e6223=WF.el("th",{scope:"col"},"Level");_e6222.appendChild(_e6223);const _e6224=WF.el("th",{scope:"col"},"Project");_e6222.appendChild(_e6224);const _e6225=WF.el("th",{scope:"col"},"What you build");_e6222.appendChild(_e6225);const _e6226=WF.el("th",{scope:"col"},"What it teaches");_e6222.appendChild(_e6226);const _e6227=WF.el("th",{scope:"col"},"Time");_e6222.appendChild(_e6227);_e6221.appendChild(_e6222);_e6220.appendChild(_e6221);const _e6228=WF.el("tbody",{});const _e6229=WF.el("tr",{});const _e6230=WF.el("td",{});const _e6231=WF.el("div",{className:"wf-markdown",markdown:"**Easy**"});_e6230.appendChild(_e6231);_e6229.appendChild(_e6230);const _e6232=WF.el("td",{});const _e6233=WF.el("div",{className:"wf-markdown",markdown:"[Todos](#easy-todos)"});_e6232.appendChild(_e6233);_e6229.appendChild(_e6232);const _e6234=WF.el("td",{},"A list of things to do: add, tick, rename, filter");_e6229.appendChild(_e6234);const _e6235=WF.el("td",{});const _e6236=WF.el("div",{className:"wf-markdown",markdown:"Types, a store with `persist`, a component, a keyed list, a filter in the address, tests that click"});_e6235.appendChild(_e6236);_e6229.appendChild(_e6235);const _e6237=WF.el("td",{},"20 minutes");_e6229.appendChild(_e6237);_e6228.appendChild(_e6229);const _e6238=WF.el("tr",{});const _e6239=WF.el("td",{});const _e6240=WF.el("div",{className:"wf-markdown",markdown:"**Medium**"});_e6239.appendChild(_e6240);_e6238.appendChild(_e6239);const _e6241=WF.el("td",{});const _e6242=WF.el("div",{className:"wf-markdown",markdown:"[Field Notes](#medium-field-notes)"});_e6241.appendChild(_e6242);_e6238.appendChild(_e6241);const _e6243=WF.el("td",{},"A notebook site, statically built, a page per note");_e6238.appendChild(_e6243);const _e6244=WF.el("td",{});const _e6245=WF.el("div",{className:"wf-markdown",markdown:"`data` files, a layout, `:slug` pages with `paths:`, Markdown pages, search and tags, what a pre-rendered page can know"});_e6244.appendChild(_e6245);_e6238.appendChild(_e6244);const _e6246=WF.el("td",{},"An hour");_e6238.appendChild(_e6246);_e6228.appendChild(_e6238);const _e6247=WF.el("tr",{});const _e6248=WF.el("td",{});const _e6249=WF.el("div",{className:"wf-markdown",markdown:"**Hard**"});_e6248.appendChild(_e6249);_e6247.appendChild(_e6248);const _e6250=WF.el("td",{});const _e6251=WF.el("div",{className:"wf-markdown",markdown:"[Pocket](#hard-pocket)"});_e6250.appendChild(_e6251);_e6247.appendChild(_e6250);const _e6252=WF.el("td",{},"A budget tracker with a dashboard, forms and two languages");_e6247.appendChild(_e6252);const _e6253=WF.el("td",{});const _e6254=WF.el("div",{className:"wf-markdown",markdown:"`Money` and `Date`, derived totals, a `persist` migration, `validate`, a dialog and shortcuts, i18n and right-to-left text, a script of your own, offline"});_e6253.appendChild(_e6254);_e6247.appendChild(_e6253);const _e6255=WF.el("td",{},"A couple of hours");_e6247.appendChild(_e6255);_e6228.appendChild(_e6247);_e6220.appendChild(_e6228);_e6218.appendChild(_e6220);const _e6256=WF.el("div",{className:"wf-markdown",markdown:"If you have not written WebFluent before, start with [the Shelf tutorial](/docs/guide/tutorial): it is a gentler first half hour."});_e6218.appendChild(_e6256);const _e6257=WF.el("h2",{className:"wf-heading",id:"before-you-start"},"Before you start");_e6218.appendChild(_e6257);const _e6258=WF.el("div",{className:"wf-markdown",markdown:"You need:\n\n- `wf` installed and on your `PATH` — `wf --version` prints `wf 5.11.0` or later ([Getting started](/docs/guide/getting-started)).\n- Chrome or Chromium on the machine, for the tests that click and for `wf verify`. Set `WF_CHROME` to its path when it is not in a usual place.\n- Git, to fetch the finished projects.\n\nEvery code block whose first line names a file — `// src/stores/Todos.wf` — is that file, or a run of lines from it, exactly as the project has it. A test holds this chapter to the projects, so the code you read here is the code that builds.\n\nTo start from a finished project instead, clone the repository and serve one:"});_e6218.appendChild(_e6258);const _e6259=Component_Terminal({lines:[({command:"git clone https://github.com/monzeromer-lab/WebFluent",output:""}),({command:"cd WebFluent/examples/tutorials/easy-todos",output:""}),({command:"wf serve",output:""})]});_e6218.appendChild(_e6259);const _e6260=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** the terminal prints `Starting dev server at http://localhost:3000/`, and that address shows the project."});_e6218.appendChild(_e6260);const _e6261=WF.el("h2",{className:"wf-heading",id:"easy-todos"},"Easy: Todos");_e6218.appendChild(_e6261);const _e6262=WF.el("div",{className:"wf-markdown",markdown:"**What you will build.** A list of things to do, kept in the reader's browser: add a todo, tick it, rename it, remove it, and show only the open ones. It is one page, one store and one component. The finished project is [`examples/tutorials/easy-todos`](https://github.com/monzeromer-lab/WebFluent/tree/master/examples/tutorials/easy-todos).\n\n**Time:** about 20 minutes.\n\n**Before you start.** You need only `wf` and Chrome. You write every file of this project yourself, and the blocks below hold each file whole, except the tests, where one of six is shown."});_e6218.appendChild(_e6262);const _e6263=WF.el("h3",{className:"wf-heading",id:"step-1-create-the-project"},"Step 1: Create the project");_e6218.appendChild(_e6263);const _e6264=WF.el("div",{className:"wf-markdown",markdown:"Make a single-page project and go into it:"});_e6218.appendChild(_e6264);const _e6265=Component_Terminal({lines:[({command:"wf init todos -t spa",output:""}),({command:"cd todos",output:""})]});_e6218.appendChild(_e6265);const _e6266=WF.el("div",{className:"wf-markdown",markdown:"Delete everything the template put in `src/` and in `tests/`: you write every file yourself, and the template's tests would fail without its pages. Then replace `webfluent.app.json` with this:"});_e6218.appendChild(_e6266);const _e6267=Component_CodeBlock({code:"{\n  \"name\": \"todos\",\n  \"version\": \"1.0.0\",\n  \"theme\": { \"name\": \"Paper\", \"dark\": \"Night\" },\n  \"build\": { \"output\": \"./build\", \"output_type\": \"spa\", \"csp\": true },\n  \"meta\": {\n    \"title\": \"Todos\",\n    \"description\": \"A small list of things to do, kept in your browser.\",\n    \"lang\": \"en\",\n    \"favicon\": \"/favicon.svg\"\n  }\n}",title:"json"});_e6218.appendChild(_e6267);const _e6268=WF.el("div",{className:"wf-markdown",markdown:"- `\"output_type\": \"spa\"` makes a single-page app: one HTML shell, with pages swapped without a reload ([Static sites and SPAs](/docs/guide/static-and-spa)).\n- `\"csp\": true` ships a content security policy and holds the build to it ([Security](/docs/guide/security)).\n- `theme` names two themes, `Paper` and `Night`, which you write in the next step.\n\n**Check it:** `wf check` prints `IO Error: No .wf files found in src/`. That is expected: `src/` is empty until the next step."});_e6218.appendChild(_e6268);const _e6269=WF.el("h3",{className:"wf-heading",id:"step-2-give-it-a-look-of-its-own"},"Step 2: Give it a look of its own");_e6218.appendChild(_e6269);const _e6270=WF.el("div",{className:"wf-markdown",markdown:"The config names a theme, so declare it first. A theme names only the design tokens it changes; every other token keeps its default ([Styling](/docs/guide/styling)). `Night` is the theme named as `\"dark\"` in the config, and the page uses it when the reader's system is set to dark:"});_e6218.appendChild(_e6270);const _e6271=Component_CodeBlock({code:"// src/theme.wf\n/// Warm paper and ink, with one teal for what you can act on.\ntheme Paper {\n    color-primary: #0F766E\n    color-background: #F6F4EF\n    color-surface: #FFFFFF\n    color-text: #1F2328\n    color-text-muted: #5E6670\n    color-border: #E4E0D8\n    font-family: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif\n    radius-md: 10px\n}\n\n/// The same page after dark.\ntheme Night {\n    color-primary: #2DD4BF\n    color-background: #14171A\n    color-surface: #1C2024\n    color-text: #ECEEF0\n    color-text-muted: #A3ABB3\n    color-border: #2C3238\n}",title:"wf"});_e6218.appendChild(_e6271);const _e6272=WF.el("div",{className:"wf-markdown",markdown:"The page you write in step 6 names classes — `card`, `todo`, `is-done`, `filters` — and `src/todos.css` styles them. The build bundles every `.css` file under `src/`, so the file needs no link. These are four of its rules; copy the whole file from the [finished project](https://github.com/monzeromer-lab/WebFluent/blob/master/examples/tutorials/easy-todos/src/todos.css):"});_e6218.appendChild(_e6272);const _e6273=Component_CodeBlock({code:".todo { flex-wrap: nowrap; padding: 0.6rem 0.25rem; border-top: 1px solid var(--color-border); }\n.todo__title { flex: 1; }\n.todo.is-done .todo__title { text-decoration: line-through; color: var(--color-text-muted); }\n.filters a.is-on { background: var(--color-background); color: var(--color-text); font-weight: 600; }",title:"css"});_e6218.appendChild(_e6273);const _e6274=WF.el("div",{className:"wf-markdown",markdown:"Each colour is a token, `var(--color-border)`, so the dark theme recolours the page with no rule of its own.\n\n**Check it:** `wf check` prints `No problems in todos.`"});_e6218.appendChild(_e6274);const _e6275=WF.el("h3",{className:"wf-heading",id:"step-3-describe-a-todo"},"Step 3: Describe a todo");_e6218.appendChild(_e6275);const _e6276=WF.el("div",{className:"wf-markdown",markdown:"A `type` names the fields a value has, and the checker holds every use to them ([Types](/docs/guide/types)). An `enum` is a fixed set of cases:"});_e6218.appendChild(_e6276);const _e6277=Component_CodeBlock({code:"// src/types.wf\n/// One thing to do.\ntype Todo {\n    id: Uuid\n    title: String\n    done: Bool = false\n}\n\n/// Which todos the list shows.\nenum Filter { all, open, done }",title:"wf"});_e6218.appendChild(_e6277);const _e6278=WF.el("div",{className:"wf-markdown",markdown:"- `Uuid` is one of the types the language brings; `uuid()` makes one.\n- `done` has a default, so a new todo can leave it out.\n- A case is written with a dot, `.open`, wherever a `Filter` is wanted.\n\nBecause the checker knows the fields, `todo.titel` is an error where it is written, and the message names the field you meant.\n\n**Check it:** `wf check` prints `No problems in todos.`"});_e6218.appendChild(_e6278);const _e6279=WF.el("h3",{className:"wf-heading",id:"step-4-write-a-store-that-remembers"},"Step 4: Write a store that remembers");_e6218.appendChild(_e6279);const _e6280=WF.el("div",{className:"wf-markdown",markdown:"A store holds state that any page or component can read ([Stores](/docs/guide/stores)). This one keeps the list:"});_e6218.appendChild(_e6280);const _e6281=Component_CodeBlock({code:"// src/stores/Todos.wf\n/// The list, kept in the browser between visits.\nstore Todos {\n    persist items: [Todo] = []\n\n    derived open = items.filter(todo => !todo.done)\n    derived done = items.filter(todo => todo.done)\n\n    action add(title: String) {\n        let text = title.trim()\n        if text == \"\" { return }\n        items = items.concat([Todo(id: uuid(), title: text)])\n    }\n\n    action toggle(id: Uuid) {\n        items = items.map(todo => if todo.id == id { { ...todo, done: !todo.done } } else { todo })\n    }\n\n    action rename(id: Uuid, title: String) {\n        let text = title.trim()\n        if text == \"\" { return }\n        items = items.map(todo => if todo.id == id { { ...todo, title: text } } else { todo })\n    }\n\n    action remove(id: Uuid) {\n        items = items.filter(todo => todo.id != id)\n    }\n\n    action clearDone() {\n        items = items.filter(todo => !todo.done)\n    }\n}",title:"wf"});_e6218.appendChild(_e6281);const _e6282=WF.el("div",{className:"wf-markdown",markdown:"- `persist` is a `state` kept in the browser's storage. The list is still there after a reload, and a second tab follows the first, with no storage code written.\n- A `derived` value follows what it reads: `open` is always the todos not yet done.\n- An action is the one place state changes. `{ ...todo, done: !todo.done }` is the todo with one field changed.\n- `rename`, `remove` and `clearDone` change the list in the same way.\n\n**Check it:** `wf check` prints seven `U04` warnings, such as ``warning[U04]: `Todos.open` is declared but never read``. That is expected: nothing reads the store yet. The page in step 6 reads every member, and the warnings go."});_e6218.appendChild(_e6282);const _e6283=WF.el("h3",{className:"wf-heading",id:"step-5-build-one-row"},"Step 5: Build one row");_e6218.appendChild(_e6283);const _e6284=WF.el("div",{className:"wf-markdown",markdown:"A component is an element of your own ([Components](/docs/guide/components)). This one draws a single todo, and lets the reader rename it in place:"});_e6218.appendChild(_e6284);const _e6285=Component_CodeBlock({code:"// src/components/TodoRow.wf\n/// One row of the list: a box to tick, the title, and buttons to rename and\n/// remove it.\ncomponent TodoRow(_ todo: Todo) {\n    use Todos\n    state editing = false\n    state draft = todo.title\n\n    action save() {\n        Todos.rename(todo.id, draft)\n        editing = false\n    }\n\n    Row(class: [\"todo\", if todo.done { \"is-done\" }], align: .center, gap: .sm) {\n        Checkbox(checked: todo.done, aria-label: \"Done: {todo.title}\") {\n            on change { Todos.toggle(todo.id) }\n        }\n        if editing {\n            // `mount:` runs when the input is made: the cursor goes straight in.\n            Input(bind: draft, aria-label: \"New title for {todo.title}\", class: \"todo__edit\", mount: (n) => n.focus()) {\n                on key(\"Enter\") { save() }\n                on key(\"Escape\") { draft = todo.title  editing = false }\n                on blur { save() }\n            }\n        } else {\n            Text(todo.title, class: \"todo__title\")\n            IconButton(icon: \"edit\", label: \"Rename {todo.title}\", class: \"todo__action\").sm {\n                on click { draft = todo.title  editing = true }\n            }\n        }\n        IconButton(icon: \"trash\", label: \"Remove {todo.title}\", class: \"todo__action\").sm {\n            on click { Todos.remove(todo.id) }\n        }\n    }\n}",title:"wf"});_e6218.appendChild(_e6285);const _e6286=WF.el("div",{className:"wf-markdown",markdown:"- `_ todo` is the component's one positional prop, so a call reads `TodoRow(todo)`.\n- Its `state` belongs to each row: renaming one row does not put the others in edit mode.\n- `class:` adds classes to the element's own. The list form may hold an `if`, which adds `is-done` only while the todo is done.\n- Every control has an accessible name. The checkbox and the icon buttons say which todo they act on, so a screen reader — and the tests in step 7 — can tell them apart ([Accessibility](/docs/guide/accessibility)).\n\n**Check it:** `wf check` prints `U03` for `TodoRow` (nothing places it yet) and four `U04` warnings. The store's `toggle`, `rename` and `remove` no longer appear: the row calls them."});_e6218.appendChild(_e6286);const _e6287=WF.el("h3",{className:"wf-heading",id:"step-6-write-the-page"},"Step 6: Write the page");_e6218.appendChild(_e6287);const _e6288=WF.el("div",{className:"wf-markdown",markdown:"The page holds the box for a new todo, the filters and the list. Here is its first half:"});_e6218.appendChild(_e6288);const _e6289=Component_CodeBlock({code:"// src/pages/Home.wf\npage Home(path: \"/\", title: \"Todos\", description: \"A small list of things to do, kept in your browser.\") {\n    use Todos\n    state draft = \"\"\n\n    // The filter lives in the address — `/?show=open` — so a reload or a\n    // shared link keeps it.\n    derived filter: Filter = if query.show == \"open\" { .open } else if query.show == \"done\" { .done } else { .all }\n    derived shown = match filter {\n        .open { Todos.open }\n        .done { Todos.done }\n        .all { Todos.items }\n    }\n\n    action add() {\n        Todos.add(draft)\n        draft = \"\"\n    }\n\n    Stack(class: \"card\", gap: .md) {\n        Row(justify: .between, align: .baseline) {\n            Heading(\"Todos\").h1\n            Text(\"{Todos.open.length} left\", class: \"count\")\n        }\n\n        Row(class: \"new\", gap: .sm) {\n            Input(bind: draft, placeholder: \"What needs doing?\", aria-label: \"New todo\") {\n                on key(\"Enter\") { add() }\n            }\n            Button(\"Add\", disabled: draft.trim() == \"\").primary {\n                on click { add() }\n            }\n        }",title:"wf"});_e6218.appendChild(_e6289);const _e6290=WF.el("div",{className:"wf-markdown",markdown:"- `bind: draft` ties the input to the state both ways: typing changes `draft`, and `draft = \"\"` empties the box.\n- `query` is the address's query string as a value, kept current. So `filter` follows the address, and `shown` follows `filter`.\n- A `match` over an enum must cover every case. If you add a fourth case to `Filter`, this `match` is an error until it handles it.\n\nThe second half draws the filters and the list, and closes the page. Add it below the first, after a blank line:"});_e6218.appendChild(_e6290);const _e6291=Component_CodeBlock({code:"// src/pages/Home.wf\n        Row(class: \"filters\", gap: .xs, align: .center) {\n            Link(\"All\", to: \"/?show=all\", class: { \"is-on\": filter == .all })\n            Link(\"Open\", to: \"/?show=open\", class: { \"is-on\": filter == .open })\n            Link(\"Done\", to: \"/?show=done\", class: { \"is-on\": filter == .done })\n            Spacer\n            if Todos.done.length > 0 {\n                Button(\"Clear done\").sm {\n                    on click { Todos.clearDone() }\n                }\n            }\n        }\n\n        if shown.length == 0 {\n            Text(if Todos.items.length == 0 { \"Nothing yet — add your first todo above.\" } else { \"Nothing here.\" }, class: \"empty\")\n        }\n        Stack(class: \"list\") {\n            for todo in shown by todo.id {\n                TodoRow(todo, animate: .fadeIn, exit: .fadeOut)\n            }\n        }\n    }\n    Text(\"Your list stays in this browser, and nowhere else.\", class: \"hint\")\n}",title:"wf"});_e6218.appendChild(_e6291);const _e6292=WF.el("div",{className:"wf-markdown",markdown:"- `for … by todo.id` is a keyed list. When a todo is renamed, or the filter hides it, only its row changes; the other rows keep their elements, and the row being edited keeps its cursor ([Control flow](/docs/guide/control-flow)).\n- `animate:` and `exit:` fade a row in and out.\n- A class map, `{ \"is-on\": filter == .all }`, turns a class on while its condition holds.\n\nLast, the `app` declaration is the frame every page sits in. `Router` marks where the current page is drawn:"});_e6218.appendChild(_e6292);const _e6293=Component_CodeBlock({code:"// src/App.wf\n// The frame every page sits in: a narrow column, centred.\napp {\n    Container(class: \"shell\") {\n        Router\n    }\n}",title:"wf"});_e6218.appendChild(_e6293);const _e6294=WF.el("div",{className:"wf-markdown",markdown:"Now start the development server in a second terminal, and leave it running. Every save rebuilds the project and reloads the page:"});_e6218.appendChild(_e6294);const _e6295=Component_Terminal({lines:[({command:"wf serve",output:""})]});_e6218.appendChild(_e6295);const _e6296=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** `wf check` prints `No problems in todos.`, and <http://localhost:3000/> shows a card headed **Todos** with `0 left` and *Nothing yet — add your first todo above.* Type a todo and press Enter: it appears, and the count reads `1 left`. Reload the page, and the todo is still there. Click **Open**, and the address becomes `/?show=open`.\n\nIf the server prints `No theme Paper is declared in this project`, you probably skipped `src/theme.wf` in step 2. If a store member shows as `U04` here, you probably left out part of the page."});_e6218.appendChild(_e6296);const _e6297=WF.el("h3",{className:"wf-heading",id:"step-7-write-tests"},"Step 7: Write tests");_e6218.appendChild(_e6297);const _e6298=WF.el("div",{className:"wf-markdown",markdown:"A test draws what it declares, then follows its steps in order. It types into the control named **New todo** and clicks the button named **Add**, the way a reader would ([Testing](/docs/guide/testing)). Create `tests/todos.wf` with this test:"});_e6218.appendChild(_e6298);const _e6299=Component_CodeBlock({code:"// tests/todos.wf\ntest \"adding a todo puts it in the list\" {\n    use Todos\n    state draft = \"\"\n    Input(bind: draft, aria-label: \"New todo\")\n    Button(\"Add\") { on click { Todos.add(draft)  draft = \"\" } }\n    for todo in Todos.items by todo.id { TodoRow(todo) }\n    Text(\"{Todos.open.length} left\")\n\n    expect \"0 left\"\n    type \"Buy bread\" into \"New todo\"\n    click \"Add\"\n    expect \"Buy bread\"\n    expect \"1 left\"\n}",title:"wf"});_e6218.appendChild(_e6299);const _e6300=WF.el("div",{className:"wf-markdown",markdown:"A test that clicks or types runs in a headless Chrome. The finished project has six tests in [`tests/todos.wf`](https://github.com/monzeromer-lab/WebFluent/blob/master/examples/tutorials/easy-todos/tests/todos.wf): two that only look at a row, and four that click — adding a todo, refusing a blank one, ticking and clearing, and renaming that keeps one row for each. Copy the file to have them all, then run them:"});_e6218.appendChild(_e6300);const _e6301=Component_Terminal({lines:[({command:"wf test",output:""})]});_e6218.appendChild(_e6301);const _e6302=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** with the whole file, `wf test` ends with `6 passed, 0 failed, 2 snapshot(s) written`. The two tests that only look write a snapshot of what they drew under `tests/__snapshots__/`, and later runs compare against it.\n\nIf a test that clicks reports that no browser was found, Chrome is not where `wf` looks: set `WF_CHROME` to its path."});_e6218.appendChild(_e6302);const _e6303=WF.el("h3",{className:"wf-heading",id:"step-8-build-it"},"Step 8: Build it");_e6218.appendChild(_e6303);const _e6304=WF.el("div",{className:"wf-markdown",markdown:"Check, test and build the project:"});_e6218.appendChild(_e6304);const _e6305=Component_Terminal({lines:[({command:"wf check",output:""}),({command:"wf test",output:""}),({command:"wf build",output:""})]});_e6218.appendChild(_e6305);const _e6306=WF.el("div",{className:"wf-markdown",markdown:"`wf check` reports every finding and writes nothing. `wf build` writes `build/`, which any static host serves — [Deploying](/docs/guide/deploying) covers GitHub Pages, Netlify and the rest. To load the built page in a real browser before you deploy, run `wf verify`: it fails on an error, a missing file or a page that draws nothing.\n\n**Check it:** `wf build` ends with `Build complete.`, and `build/` holds `index.html`, `app.js` and `styles.css`."});_e6218.appendChild(_e6306);const _e6307=WF.el("h3",{className:"wf-heading",id:"what-you-built-in-todos"},"What you built in Todos");_e6218.appendChild(_e6307);const _e6308=WF.el("div",{className:"wf-markdown",markdown:"- A `type` and an `enum`, held to every use ([Types](/docs/guide/types)).\n- A store whose list survives a reload with `persist`, and `derived` values that follow it ([Stores](/docs/guide/stores)).\n- A component with state of its own, and accessible names on every control ([Components](/docs/guide/components)).\n- A keyed list, and a filter kept in the address with `query` ([Control flow](/docs/guide/control-flow)).\n- A theme with a dark variant, and the project's own stylesheet ([Styling](/docs/guide/styling)).\n- Tests that look and tests that click ([Testing](/docs/guide/testing))."});_e6218.appendChild(_e6308);const _e6309=WF.el("h2",{className:"wf-heading",id:"medium-field-notes"},"Medium: Field Notes");_e6218.appendChild(_e6309);const _e6310=WF.el("div",{className:"wf-markdown",markdown:"**What you will build.** A notebook kept in public — notes from a garden, a kitchen and a few trips — built as a static site. The notes are a JSON file the build reads. Every page, including one page per note, is written out as HTML that a search engine can read. The one thing a reader changes, the notes they save for later, stays in their browser. The finished project is [`examples/tutorials/medium-field-notes`](https://github.com/monzeromer-lab/WebFluent/tree/master/examples/tutorials/medium-field-notes).\n\n**Time:** about an hour.\n\n**Before you start.** You need `wf`, Chrome and a copy of the repository (see [Before you start](#before-you-start) above). This tutorial shows the part of each file that teaches something new, so work in the finished project and read each file as its step comes up:"});_e6218.appendChild(_e6310);const _e6311=Component_Terminal({lines:[({command:"cd WebFluent/examples/tutorials/medium-field-notes",output:""}),({command:"wf serve",output:""})]});_e6218.appendChild(_e6311);const _e6312=WF.el("div",{className:"wf-markdown",markdown:"The Todos tutorial explains state, stores and components; this one assumes them."});_e6218.appendChild(_e6312);const _e6313=WF.el("h3",{className:"wf-heading",id:"step-1-create-a-static-project-and-its-look"},"Step 1: Create a static project and its look");_e6218.appendChild(_e6313);const _e6314=WF.el("div",{className:"wf-markdown",markdown:"A new project of this kind starts from the `static` template:"});_e6218.appendChild(_e6314);const _e6315=Component_Terminal({lines:[({command:"wf init field-notes -t static",output:""}),({command:"cd field-notes",output:""})]});_e6218.appendChild(_e6315);const _e6316=WF.el("div",{className:"wf-markdown",markdown:"The project's `webfluent.app.json`:"});_e6218.appendChild(_e6316);const _e6317=Component_CodeBlock({code:"{\n  \"name\": \"field-notes\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Field Notes\",\n  \"theme\": { \"name\": \"Meadow\", \"dark\": \"Dusk\" },\n  \"build\": {\n    \"output\": \"./build\",\n    \"ssg\": true,\n    \"csp\": true\n  },\n  \"meta\": {\n    \"title\": \"Field Notes\",\n    \"description\": \"Notes from a small garden, a busy kitchen and the roads between them.\",\n    \"lang\": \"en\",\n    \"site_url\": \"https://field-notes.example.com\",\n    \"site_name\": \"Field Notes\",\n    \"favicon\": \"/favicon.svg\",\n    \"image\": \"/card.png\",\n    \"sitemap\": true\n  }\n}",title:"json"});_e6218.appendChild(_e6317);const _e6318=WF.el("div",{className:"wf-markdown",markdown:"- `\"ssg\": true` pre-renders every page to its own `index.html`. When the page loads, the script takes it over in place — *hydration* ([Static sites and SPAs](/docs/guide/static-and-spa)).\n- `site_url` lets the build write what search engines and link previews read: a canonical address, Open Graph tags, JSON-LD, `sitemap.xml` and `robots.txt` ([Content](/docs/guide/content)).\n\nThe dark theme names only the tokens that change:"});_e6218.appendChild(_e6318);const _e6319=Component_CodeBlock({code:"// src/theme.wf\n/// The dark theme: only the tokens that change.\ntheme Dusk {\n    color-primary: #86C9A6\n    color-secondary: #E8A086\n    color-background: #121614\n    color-surface: #1A201D\n    color-text: #E9E5DA\n    color-text-muted: #A6AFA9\n    color-border: #2B3430\n    paper-raised: #171C19\n    tag-bg: #213129\n    tag-text: #A9DCC1\n}",title:"wf"});_e6218.appendChild(_e6319);const _e6320=WF.el("div",{className:"wf-markdown",markdown:"The light theme, `Meadow`, sets the same names. A theme may declare tokens of its own, such as `paper-raised` and `tag-bg`. The project's stylesheet, `src/styles.css`, reads every colour as a token (`var(--tag-bg)`), so the dark theme needs no rule of its own ([Design tokens](/docs/guide/tokens)).\n\n**Check it:** with `wf serve` running, set your system to dark mode. The page turns dark green and cream without a reload."});_e6218.appendChild(_e6320);const _e6321=WF.el("h3",{className:"wf-heading",id:"step-2-type-the-data"},"Step 2: Type the data");_e6218.appendChild(_e6321);const _e6322=WF.el("div",{className:"wf-markdown",markdown:"The notes are data, and a `type` says what each one holds:"});_e6218.appendChild(_e6322);const _e6323=Component_CodeBlock({code:"// src/types.wf\n/// One note in the notebook.\ntype Note {\n    slug: String\n    title: String\n    date: Date\n    tags: [String]\n    summary: String\n    minutes: Number\n    body: String\n}\n\n/// Every note, read from `notes.json` when the site is built.\ndata notes: [Note] = \"notes.json\"",title:"wf"});_e6218.appendChild(_e6323);const _e6324=WF.el("div",{className:"wf-markdown",markdown:"- `data` reads a JSON file at build time. The result is a constant, typed by the annotation, inlined into the bundle and seeded into every pre-rendered page ([Data](/docs/guide/data)).\n- The checker holds the program to `Note`: a page that reads `note.titel` is an error where it is written.\n- `date` is a `Date`: a plain `\"2026-03-08\"` string the language knows how to format. `{note.date:.date(long)}` shows `March 8, 2026`.\n\n`src/notes.json` holds seven notes, each with a Markdown `body`.\n\n**Check it:** `wf check` prints `No problems in field-notes.` If one note in `notes.json` has a field that `Note` does not declare, the check reports `T05` at the `data` line and names the field; if a note leaves out a field `Note` requires, it reports `C01`."});_e6218.appendChild(_e6324);const _e6325=WF.el("h3",{className:"wf-heading",id:"step-3-write-the-shell-and-a-layout"},"Step 3: Write the shell and a layout");_e6218.appendChild(_e6325);const _e6326=WF.el("div",{className:"wf-markdown",markdown:"The `app` declaration wraps every page. The current page is drawn where `Router` stands, inside `<main>`, so the skip link each page carries jumps past the navigation ([Pages and routing](/docs/guide/pages-and-routing)). The start of `src/App.wf`:"});_e6218.appendChild(_e6326);const _e6327=Component_CodeBlock({code:"// src/App.wf\napp {\n    use Saved\n\n    Navbar(class: \"site-nav\") {\n        Navbar.Brand {\n            Link(\"Field Notes\", to: \"/\", class: \"brand\")\n        }\n        Navbar.Links {\n            Link(\"Notes\", to: \"/\")\n            Link(\"Tags\", to: \"/tags\")\n            Link(to: \"/saved\", class: \"saved-link\") {\n                Text(\"Saved\")\n                if Saved.count > 0 {\n                    Badge(\"{Saved.count}\").pill\n                }\n            }\n            Link(\"About\", to: \"/about\")\n        }\n        Navbar.Actions {\n            ThemeToggle\n        }\n    }\n\n    Router(transition: .fade, duration: \"160ms\")",title:"wf"});_e6218.appendChild(_e6327);const _e6328=WF.el("div",{className:"wf-markdown",markdown:"- The link whose `to:` is the page shown is marked `aria-current=\"page\"`.\n- `ThemeToggle` is two icon buttons that call `setTheme(\"dark\")` and `setTheme(\"light\")`. The reader's choice is kept across visits.\n- `Router(transition: .fade, duration: \"160ms\")` fades one page out and the next in.\n\nEach page names the column it is set in with `layout:` — a component whose default slot is the page:"});_e6218.appendChild(_e6328);const _e6329=Component_CodeBlock({code:"// src/components/Sheet.wf\n/// The column a page is set in, and the frame every page names with\n/// `layout: Sheet`. A narrow sheet is for reading; a wide one holds a grid.\ncomponent Sheet(wide: Bool = false) {\n    slot\n    Container(class: [\"sheet\", if wide { \"sheet--wide\" }]) {\n        children\n    }\n}",title:"wf"});_e6218.appendChild(_e6329);const _e6330=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** the navbar shows **Notes**, **Tags**, **Saved** and **About**. Click **Tags**: the page fades over, and the **Tags** link is marked as the current page."});_e6218.appendChild(_e6330);const _e6331=WF.el("h3",{className:"wf-heading",id:"step-4-build-a-card"},"Step 4: Build a card");_e6218.appendChild(_e6331);const _e6332=WF.el("div",{className:"wf-markdown",markdown:"A card shows a note at a glance:"});_e6218.appendChild(_e6332);const _e6333=Component_CodeBlock({code:"// src/components/NoteCard.wf\n/// A note at a glance: when it was written, its title, a summary, its tags\n/// and the button that saves it.\ncomponent NoteCard(\n    _ note: Note,\n    /// Keeps the card in the page but out of sight — what a filter does.\n    hidden: Bool = false\n) {\n    Card(class: \"note-card\", hidden: hidden) {\n        Stack(gap: .sm) {\n            Row(justify: .between, align: .center, gap: .sm) {\n                Text(\"{note.date:.date(long)} · {note.minutes} min read\", class: \"note-meta\").sm\n                SaveButton(note.slug, title: note.title)\n            }\n            Link(to: \"/notes/{note.slug}\", class: \"note-card__link\") {\n                Heading(note.title).h2\n            }\n            Text(note.summary, class: \"note-card__summary\")\n            TagList(note.tags)\n        }\n    }\n}",title:"wf"});_e6218.appendChild(_e6333);const _e6334=WF.el("div",{className:"wf-markdown",markdown:"- A `///` comment above a component or a prop is its documentation. Your editor shows it when you hover a call ([Components](/docs/guide/components)).\n- A splice may say how to show its value: `{note.date:.date(long)}` is `format(note.date, .date, \"long\")`, written where it is read ([Expressions](/docs/guide/expressions)).\n- `TagList` is a row of `#tag` links to `/?tag=…`.\n\n**Check it:** the front page shows a card per note, each with a line such as `March 8, 2026 · 4 min read`, a title, a summary and its tags."});_e6218.appendChild(_e6334);const _e6335=WF.el("h3",{className:"wf-heading",id:"step-5-search-and-filter-the-front-page"},"Step 5: Search and filter the front page");_e6218.appendChild(_e6335);const _e6336=WF.el("div",{className:"wf-markdown",markdown:"The front page lists every note, narrowed by a search box and by the tag in the address. `NoteFinder` works the list out:"});_e6218.appendChild(_e6336);const _e6337=Component_CodeBlock({code:"// src/components/NoteFinder.wf\n    state q = \"\"\n\n    derived needle = q.trim().toLowerCase()\n    derived newest = all.sortBy(n => n.date).reverse()\n    derived shown = newest.filter(n =>\n        (tag == \"\" || n.tags.includes(tag))\n        && (needle == \"\"\n            || n.title.toLowerCase().includes(needle)\n            || n.summary.toLowerCase().includes(needle)))\n    derived visible = shown.map(n => n.slug)\n    derived allTags = all.flatMap(n => n.tags).unique().sort()",title:"wf"});_e6218.appendChild(_e6337);const _e6338=WF.el("div",{className:"wf-markdown",markdown:"`q` is bound to the search box, and everything else follows it. `sortBy`, `flatMap` and `unique` are list helpers the language brings. Each also runs at build time, so the pre-rendered page shows the sorted list ([State and reactivity](/docs/guide/state)).\n\nA static site adds one idea here. Its HTML is written once, before any reader arrives, so the HTML cannot depend on what only the browser knows, such as the address's query or what is in storage. So the finder draws every note and hides the ones that do not match:"});_e6218.appendChild(_e6338);const _e6339=Component_CodeBlock({code:"// src/components/NoteFinder.wf\n            // Every note is drawn, and the ones that do not match are hidden.\n            // A pre-rendered page cannot know the URL's query, so a list\n            // filtered by it would be missing from the HTML; this way the\n            // page carries every note, and the filter applies once it is live.\n            for note in newest by note.slug {\n                NoteCard(note, hidden: !visible.includes(note.slug))\n            }",title:"wf"});_e6218.appendChild(_e6339);const _e6340=WF.el("div",{className:"wf-markdown",markdown:"The HTML then holds every note, for a reader without script and for a search engine, and the filter applies the moment the page is live. The front page hands the finder the address's tag:"});_e6218.appendChild(_e6340);const _e6341=Component_CodeBlock({code:"// src/pages/Home.wf\n        // `query.tag` is the URL's `?tag=…`; it is missing when the URL has\n        // none, and `?? \"\"` turns that into the finder's \"every note\".\n        NoteFinder(notes, tag: query.tag ?? \"\")",title:"wf"});_e6218.appendChild(_e6341);const _e6342=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** the front page reads `7 of 7 notes`. Type `tomato` in the search box, and the count and the cards narrow as you type. Open `/?tag=garden`, and only the notes tagged `garden` show. Run `wf build` and open `build/index.html` in a text editor: all seven notes are in it.\n\nIf a filtered list is empty in the built HTML, you probably filtered the `for` itself by `query`; hide the cards instead, as above."});_e6218.appendChild(_e6342);const _e6343=WF.el("h3",{className:"wf-heading",id:"step-6-give-each-note-a-page"},"Step 6: Give each note a page");_e6218.appendChild(_e6343);const _e6344=WF.el("div",{className:"wf-markdown",markdown:"Each note gets a page at `/notes/<slug>`:"});_e6218.appendChild(_e6344);const _e6345=Component_CodeBlock({code:"// src/pages/NotePage.wf\npage NotePage(path: \"/notes/:slug\", slug: String,\n    title: \"{notes.find(n => n.slug == slug)?.title ?? slug} — Field Notes\",\n    description: \"{notes.find(n => n.slug == slug)?.summary ?? slug}\",\n    type: \"article\",\n    layout: Sheet,\n    paths: notes.map(n => n.slug)) {\n\n    derived note = notes.find(n => n.slug == slug)",title:"wf"});_e6218.appendChild(_e6345);const _e6346=WF.el("div",{className:"wf-markdown",markdown:"- `:slug` in the path is a typed parameter of the page.\n- `paths:` names the values a static build renders the page for: one `notes/<slug>/index.html` per note, each listed in the sitemap ([Content](/docs/guide/content)).\n- `title:` and `description:` may be worked out from the parameters, so each note's search result shows its own title and summary.\n\nThe body of the page is the note's Markdown:"});_e6218.appendChild(_e6346);const _e6347=Component_CodeBlock({code:"// src/pages/NotePage.wf\n            Markdown(n.body)",title:"wf"});_e6218.appendChild(_e6347);const _e6348=WF.el("div",{className:"wf-markdown",markdown:"`Markdown` renders headings, lists, quotes, emphasis and links, at build time and live. It escapes the text first, so HTML in a note is shown, not run ([Elements](/docs/guide/elements)). Below the note, `related` lists the three newest notes that share a tag with it — a `derived` value like any other.\n\n**Check it:** click a note's title. Its page shows the whole note, and the browser tab shows its title followed by `— Field Notes`. After `wf build`, `build/notes/` holds seven folders, one per note."});_e6218.appendChild(_e6348);const _e6349=WF.el("h3",{className:"wf-heading",id:"step-7-list-the-tags-and-write-a-page-in-markdown"},"Step 7: List the tags, and write a page in Markdown");_e6218.appendChild(_e6349);const _e6350=WF.el("div",{className:"wf-markdown",markdown:"The Tags page groups the notes under each tag:"});_e6218.appendChild(_e6350);const _e6351=Component_CodeBlock({code:"// src/pages/Tags.wf\n        Grid(columns: { base: 1, md: 2 }, gap: .md, align: .start) {\n            for tag in allTags by tag {\n                derived filed = notes.filter(n => n.tags.includes(tag)).sortBy(n => n.date).reverse()",title:"wf"});_e6218.appendChild(_e6351);const _e6352=WF.el("div",{className:"wf-markdown",markdown:"- A layout prop takes one value per breakpoint: one column on a phone, two from `md` up. It compiles to a media query, so the first paint is already right ([Styling](/docs/guide/styling)).\n- A `derived` value inside a `for` is worked out for each item.\n\nThe About page is not a `.wf` file at all. `src/about.md` is a page: its front matter names its path, title, description and layout, and the rest is its Markdown:"});_e6218.appendChild(_e6352);const _e6353=Component_CodeBlock({code:"---\npath: /about\ntitle: About — Field Notes\ndescription: Who keeps this notebook, why it exists, and how the site is built.\nlayout: Sheet\n---\n# About",title:"markdown"});_e6218.appendChild(_e6353);const _e6354=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** `/tags` shows one card per tag, in one column on a narrow window and two on a wide one. `/about` shows the About page in the same column as the others."});_e6218.appendChild(_e6354);const _e6355=WF.el("h3",{className:"wf-heading",id:"step-8-keep-the-reader-s-saved-notes"},"Step 8: Keep the reader's saved notes");_e6218.appendChild(_e6355);const _e6356=WF.el("div",{className:"wf-markdown",markdown:"A store keeps the notes this reader saves:"});_e6218.appendChild(_e6356);const _e6357=Component_CodeBlock({code:"// src/stores/Saved.wf\n/// The notes this reader has saved for later, kept in their browser.\nstore Saved {\n    persist slugs: [String] = []\n\n    derived count = slugs.length",title:"wf"});_e6218.appendChild(_e6357);const _e6358=WF.el("div",{className:"wf-markdown",markdown:"`persist` keeps the list in the browser across visits. There is no account, and nothing is sent anywhere ([Stores](/docs/guide/stores)).\n\nThe button that saves a note says whether it is pressed, the way assistive technology reads it:"});_e6218.appendChild(_e6358);const _e6359=Component_CodeBlock({code:"// src/components/SaveButton.wf\n/// Saves a note for later, or takes it off the saved list.\ncomponent SaveButton(_ slug: String, title: String) {\n    use Saved\n\n    Button(if Saved.slugs.includes(slug) { \"Saved\" } else { \"Save\" },\n        aria-pressed: Saved.slugs.includes(slug),\n        aria-label: if Saved.slugs.includes(slug) { \"Saved: {title}\" } else { \"Save: {title}\" },\n        class: \"save-button\").sm.outlined {\n        on click { Saved.toggle(slug) }\n    }\n}",title:"wf"});_e6218.appendChild(_e6359);const _e6360=WF.el("div",{className:"wf-markdown",markdown:"`aria-pressed` follows the state, and `styles.css` styles the pressed button with `[aria-pressed=\"true\"]`, so the look and the meaning are one attribute ([Accessibility](/docs/guide/accessibility)). The Saved page lists `notes.filter(n => Saved.slugs.includes(n.slug))`, and the navbar's badge shows `Saved.count`.\n\n**Check it:** click **Save** on a card. It reads **Saved**, and the navbar shows a `1` badge beside **Saved**. Reload the page: the note is still saved, and `/saved` lists it."});_e6218.appendChild(_e6360);const _e6361=WF.el("h3",{className:"wf-heading",id:"step-9-test-it-and-run-the-checks-a-static-site-needs"},"Step 9: Test it, and run the checks a static site needs");_e6218.appendChild(_e6361);const _e6362=WF.el("div",{className:"wf-markdown",markdown:"A test reads the project's `data` file, as any page does ([Testing](/docs/guide/testing)):"});_e6218.appendChild(_e6362);const _e6363=Component_CodeBlock({code:"// tests/NoteFinder.wf\ntest \"a search that matches nothing says so, and clears\" {\n    NoteFinder(notes)\n    type \"zeppelin\" into \"Search the notes\"\n    expect \"Nothing matches\"\n    expect \"0 of 7 notes\"\n    click \"Clear the search\"\n    expect \"7 of 7 notes\"\n    expect not \"Nothing matches\"\n}",title:"wf"});_e6218.appendChild(_e6363);const _e6364=WF.el("div",{className:"wf-markdown",markdown:"The project has six tests. Run them, check with warnings counted as failures, build, and load the result in a browser:"});_e6218.appendChild(_e6364);const _e6365=Component_Terminal({lines:[({command:"wf test",output:""}),({command:"wf check --deny-warnings",output:""}),({command:"wf build",output:""}),({command:"wf verify",output:""})]});_e6218.appendChild(_e6365);const _e6366=WF.el("div",{className:"wf-markdown",markdown:"`wf verify` loads every route of the built site in a headless Chrome — each note's page at its `paths:` value — and fails on an error, a missing file or a page that draws nothing ([Command line](/docs/guide/cli)).\n\n**Check it:** `wf test` reports `6 passed`, `wf build` reports `SSG: pre-rendered static pages`, and `wf verify` ends with `0 problem(s)`. `build/` is ready for any static host."});_e6218.appendChild(_e6366);const _e6367=WF.el("h3",{className:"wf-heading",id:"what-you-built-in-field-notes"},"What you built in Field Notes");_e6218.appendChild(_e6367);const _e6368=WF.el("div",{className:"wf-markdown",markdown:"- A static build, with canonical addresses, a sitemap and link previews ([Content](/docs/guide/content)).\n- Typed data read from a JSON file at build time ([Data](/docs/guide/data)).\n- A shell, and a layout every page names ([Pages and routing](/docs/guide/pages-and-routing)).\n- A page per note from one `:slug` page and `paths:`, and a page written in Markdown ([Content](/docs/guide/content)).\n- A search and a filter that work in pre-rendered HTML ([Static sites and SPAs](/docs/guide/static-and-spa)).\n- A reader's saved list, with a pressed state assistive technology reads ([Accessibility](/docs/guide/accessibility))."});_e6218.appendChild(_e6368);const _e6369=WF.el("h2",{className:"wf-heading",id:"hard-pocket"},"Hard: Pocket");_e6218.appendChild(_e6369);const _e6370=WF.el("div",{className:"wf-markdown",markdown:"**What you will build.** A personal budget tracker that lives entirely in the reader's browser: money in and money out, a budget per category, what is left of it this month, six months of bars, two languages, a CSV export and import, and a page that keeps working offline. There is no server and no account. The finished project is [`examples/tutorials/hard-pocket`](https://github.com/monzeromer-lab/WebFluent/tree/master/examples/tutorials/hard-pocket).\n\n**Time:** a couple of hours.\n\n**Before you start.** You need `wf`, Chrome and a copy of the repository (see [Before you start](#before-you-start) above). This tutorial assumes the Todos tutorial, and each step links the chapter that goes deeper. Like Field Notes, it shows the part of each file that teaches something new, so work in the finished project:"});_e6218.appendChild(_e6370);const _e6371=Component_Terminal({lines:[({command:"cd WebFluent/examples/tutorials/hard-pocket",output:""}),({command:"wf serve",output:""})]});_e6218.appendChild(_e6371);const _e6372=WF.el("h3",{className:"wf-heading",id:"step-1-configure-the-project"},"Step 1: Configure the project");_e6218.appendChild(_e6372);const _e6373=WF.el("div",{className:"wf-markdown",markdown:"The project's `webfluent.app.json`:"});_e6218.appendChild(_e6373);const _e6374=Component_CodeBlock({code:"{\n  \"name\": \"pocket\",\n  \"version\": \"1.0.0\",\n  \"author\": \"WebFluent tutorials\",\n  \"theme\": { \"name\": \"Pocket\", \"dark\": \"PocketNight\" },\n  \"build\": {\n    \"output\": \"./build\",\n    \"output_type\": \"spa\",\n    \"csp\": true\n  },\n  \"meta\": {\n    \"title\": \"Pocket\",\n    \"description\": \"A budget that lives in your browser: income, spending and what is left, month by month.\",\n    \"lang\": \"en\"\n  },\n  \"i18n\": {\n    \"default_locale\": \"en\",\n    \"locales\": [\"en\", \"ar\"],\n    \"dir\": \"src/translations\"\n  },\n  \"offline\": {\n    \"precache\": [\"/\", \"/entries\", \"/categories\", \"/settings\"],\n    \"fallback\": \"/\"\n  }\n}",title:"json"});_e6218.appendChild(_e6374);const _e6375=WF.el("div",{className:"wf-markdown",markdown:"It adds three things to the Todos config:\n\n- `i18n` names the languages and the folder their messages live in ([Internationalization](/docs/guide/i18n)).\n- `offline` makes `wf build` write a service worker that stores the four pages, so a second visit opens with no network ([Offline](/docs/guide/offline)).\n- `theme` names two themes, light and dark, and the build ships both.\n\n**Check it:** `wf build` prints a line that starts `Offline: sw.js`, then `2 locales` in its summary."});_e6218.appendChild(_e6375);const _e6376=WF.el("h3",{className:"wf-heading",id:"step-2-describe-money"},"Step 2: Describe money");_e6218.appendChild(_e6376);const _e6377=WF.el("div",{className:"wf-markdown",markdown:"The ledger's types use four of the types the language brings:"});_e6218.appendChild(_e6377);const _e6378=Component_CodeBlock({code:"// src/types.wf\n/// Which way the money went.\nenum Kind { income, expense }\n\n/// Something money is spent on, with what the reader means to spend on it\n/// in a month.\ntype Category {\n    id: String\n    name: String\n    color: Color\n    budget: Money\n}\n\n/// One line of the ledger: money in, or money out.\ntype Entry {\n    id: Uuid\n    date: Date\n    amount: Money\n    kind: Kind\n    category: String\n    note: String = \"\"\n}",title:"wf"});_e6218.appendChild(_e6378);const _e6379=WF.el("div",{className:"wf-markdown",markdown:"`Money`, `Date`, `Color` and `Uuid` are each a plain JSON value at run time ([Types](/docs/guide/types)). Money is kept in minor units, `{ amount: 1299, currency: \"USD\" }`, so a sum never drifts by a fraction of a cent. You write it `$12.99` and show it with `format(m)`. What the language works out is a call — `a.plus(b)`, `a.minus(b)`, `ONE.times(12.5)` — and what the value carries is a field: `m.amount`. Two constants give every sum a starting point:"});_e6218.appendChild(_e6379);const _e6380=Component_CodeBlock({code:"// src/types.wf\n/// Nothing yet: the starting point every sum adds to.\nconst ZERO: Money = $0.00\n\n/// One dollar — `ONE.times(12.5)` is $12.50, rounded to the cent.\nconst ONE: Money = $1.00",title:"wf"});_e6218.appendChild(_e6380);const _e6381=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** `wf check` prints `No problems in pocket.` Change `$0.00` to `$0.001`, and the check refuses it: money has two decimals in dollars. Change it back."});_e6218.appendChild(_e6381);const _e6382=WF.el("h3",{className:"wf-heading",id:"step-3-add-up-the-ledger"},"Step 3: Add up the ledger");_e6218.appendChild(_e6382);const _e6383=WF.el("div",{className:"wf-markdown",markdown:"Every figure on every page is a `derived` value of the `Ledger` store:"});_e6218.appendChild(_e6383);const _e6384=Component_CodeBlock({code:"// src/stores/Ledger.wf\n    derived today = now.date()\n    derived newestFirst = entries.sortBy(e => e.date).reverse()\n\n    derived income = sum(entries.filter(e => e.kind == .income))\n    derived spent = sum(entries.filter(e => e.kind == .expense))\n    derived balance = income.minus(spent)\n\n    derived thisMonth = entries.filter(e => e.date.startOfMonth().isSame(today.startOfMonth()))\n    derived monthIncome = sum(thisMonth.filter(e => e.kind == .income))\n    derived monthSpent = sum(thisMonth.filter(e => e.kind == .expense))\n    derived monthBudget = categories.reduce((s, c) => s.plus(c.budget), ZERO)\n    derived budgetLeft = monthBudget.minus(monthSpent)",title:"wf"});_e6218.appendChild(_e6384);const _e6385=WF.el("div",{className:"wf-markdown",markdown:"Add an entry, and the balance, this month's spending, each budget bar and the chart all follow, with no code written to keep them in step ([Stores](/docs/guide/stores)). `now` is the browser's clock as a value, so `today` turns over at midnight. `sum` is an action that only returns a value, which a derived value may call:"});_e6218.appendChild(_e6385);const _e6386=Component_CodeBlock({code:"// src/stores/Ledger.wf\n    // The money in a list of entries, added up.\n    action sum(list: [Entry]) {\n        return list.reduce((total, e) => total.plus(e.amount), ZERO)\n    }",title:"wf"});_e6218.appendChild(_e6386);const _e6387=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** the dashboard shows a balance, this month's income and spending, and what is left of the budget. Each is a sum of the sample ledger."});_e6218.appendChild(_e6387);const _e6388=WF.el("h3",{className:"wf-heading",id:"step-4-change-the-stored-shape-without-losing-data"},"Step 4: Change the stored shape without losing data");_e6218.appendChild(_e6388);const _e6389=WF.el("div",{className:"wf-markdown",markdown:"What a `persist` keeps outlives the build that wrote it: a reader who visited last month has last month's shape in their browser. The entries declare which version of the shape this build writes, and how to bring an older one forward:"});_e6218.appendChild(_e6389);const _e6390=Component_CodeBlock({code:"// src/stores/Ledger.wf\n    // Version 1 of Pocket kept an amount as a plain, signed number of\n    // dollars (`-52.4` was money out). Version 2 keeps a `Money` and a\n    // `Kind`, so `migrate 1 -> 2` turns what a returning reader's browser\n    // holds into the new shape instead of throwing it away.\n    persist entries: [Entry] = SAMPLE_ENTRIES.map(s => Entry(\n            id: s.id,\n            date: now.date().minus(days: s.ago),\n            amount: s.amount,\n            kind: s.kind,\n            category: s.category,\n            note: s.note,\n        )) {\n        version: 2\n        migrate 1 -> 2 {\n            old.map(e => Entry(\n                    id: e.id,\n                    date: e.date,\n                    amount: ONE.times(Math.abs(e.amount)),\n                    kind: if e.amount < 0 { .expense } else { .income },\n                    category: e.category,\n                    note: e.note ?? \"\",\n                ))\n        }\n    }",title:"wf"});_e6218.appendChild(_e6390);const _e6391=WF.el("div",{className:"wf-markdown",markdown:"- `version: 2` says which shape this build writes.\n- `migrate 1 -> 2` brings an older value forward. Its body receives the stored value as `old`.\n- If you raise the version with no migration, the build warns (`P01`). If you change the shape without raising the version, it warns too (`D04`), from the shapes it keeps in `.wf-cache/` ([Stores](/docs/guide/stores)).\n- A first visit opens on a sample ledger dated from today, so the dashboard is never empty.\n\n**Check it:** `wf check --deny-warnings` passes. Delete the `migrate` block and check again: the check reports `P01`. Put the block back."});_e6218.appendChild(_e6391);const _e6392=WF.el("h3",{className:"wf-heading",id:"step-5-fit-the-shell-to-the-screen"},"Step 5: Fit the shell to the screen");_e6218.appendChild(_e6392);const _e6393=WF.el("div",{className:"wf-markdown",markdown:"The shell draws a `Sidebar` when `viewport.lg` holds, and a top bar with a drawer when it does not. This is the drawer:"});_e6218.appendChild(_e6393);const _e6394=Component_CodeBlock({code:"// src/App.wf\n            if Ui.menuOpen {\n                Host(tag: \"div\", class: \"scrim\") { on click { Ui.closeAll() } }\n                Stack(gap: .md, class: \"drawer\", animate: .slideRight, exit: .fadeOut) {\n                    on click { Ui.menuOpen = false }\n                    Brand\n                    NavLinks\n                }\n            }",title:"wf"});_e6218.appendChild(_e6394);const _e6395=WF.el("div",{className:"wf-markdown",markdown:"- `viewport` is the window's size as a value. It follows `matchMedia`, so the switch happens once, as the window crosses the breakpoint ([Styling](/docs/guide/styling)).\n- The layout itself — grids that are one column on a phone — uses responsive values, `Grid(columns: { base: 1, lg: 2 })`, which need no script.\n- A second store, `Ui`, holds what the interface is doing — the dialog, the menu, the notices — apart from what the ledger holds.\n\n**Check it:** on a wide window, the sidebar shows. Narrow the window: a top bar replaces it, and its menu button opens the drawer, which a click on the dimmed page behind it closes."});_e6218.appendChild(_e6395);const _e6396=WF.el("h3",{className:"wf-heading",id:"step-6-draw-a-dashboard-from-elements"},"Step 6: Draw a dashboard from elements");_e6218.appendChild(_e6396);const _e6397=WF.el("div",{className:"wf-markdown",markdown:"The built-in `Chart` draws at build time, from data the build can see. This ledger exists only in the reader's browser, so the chart is made of plain elements whose heights follow the store:"});_e6218.appendChild(_e6397);const _e6398=Component_CodeBlock({code:"// src/components/MonthChart.wf\n/// Six months of money in and money out, as pairs of bars.\n///\n/// The built-in `Chart` draws at build time, from data the build can see.\n/// This ledger only exists in the reader's browser, so the chart is made of\n/// plain elements whose heights follow the store: `height: {share}%` is a\n/// style value that reads state, and repaints when it changes.\ncomponent MonthChart(months: [MonthTotal], top: Number) {\n    Stack(gap: .sm) {\n        Row(class: \"chart\", align: .end, role: \"img\", aria-label: t(\"chart.label\")) {\n            for m in months by m.month {\n                Stack(gap: .xs, align: .center, class: \"chart__month\") {\n                    Row(gap: .xs, align: .end, class: \"chart__bars\") {\n                        Host(tag: \"span\", class: \"chart__bar chart__bar--in\") {\n                            style { height: {m.income.amount / top * 100}% }\n                        }\n                        Host(tag: \"span\", class: \"chart__bar chart__bar--out\") {\n                            style { height: {m.spent.amount / top * 100}% }\n                        }\n                    }",title:"wf"});_e6218.appendChild(_e6398);const _e6399=WF.el("div",{className:"wf-markdown",markdown:"- A `{…}` in a style value reads state, and the property follows it ([Styling](/docs/guide/styling)).\n- The chart is one `role=\"img\"` with a label, so a screen reader hears what it shows rather than twelve unnamed boxes ([Accessibility](/docs/guide/accessibility)).\n\nThe figures above the chart are one component, placed four times:"});_e6218.appendChild(_e6399);const _e6400=Component_CodeBlock({code:"// src/pages/Dashboard.wf\n    Grid(columns: { base: 2, xl: 4 }, gap: .md) {\n        KpiCard(t(\"kpi.balance\"), value: Ledger.balance, note: t(\"kpi.balanceNote\"))\n        KpiCard(t(\"kpi.income\"), value: Ledger.monthIncome, note: t(\"kpi.thisMonth\"), lean: .good)\n        KpiCard(t(\"kpi.spent\"), value: Ledger.monthSpent, note: t(\"kpi.thisMonth\"), lean: .bad)\n        KpiCard(t(\"kpi.left\"), value: Ledger.budgetLeft, note: t(\"kpi.leftNote\", { budget: format(Ledger.monthBudget) }),\n            lean: if Ledger.budgetLeft.amount < 0 { .bad } else { .good })\n    }",title:"wf"});_e6218.appendChild(_e6400);const _e6401=WF.el("div",{className:"wf-markdown",markdown:"`lean` is an enum prop. A component writes its enum props to its root element, here as `data-lean=\"good\"`, and `pocket.css` colours the card by that attribute ([Components](/docs/guide/components)).\n\n**Check it:** the dashboard shows four cards and six pairs of bars. Add an expense in step 9's dialog, and this month's bar and the **Spent** card grow at once."});_e6218.appendChild(_e6401);const _e6402=WF.el("h3",{className:"wf-heading",id:"step-7-keep-the-filters-in-the-address"},"Step 7: Keep the filters in the address");_e6218.appendChild(_e6402);const _e6403=WF.el("div",{className:"wf-markdown",markdown:"The Entries page reads its filters from the address:"});_e6218.appendChild(_e6403);const _e6404=Component_CodeBlock({code:"// src/pages/Entries.wf\n    // The filters live in the address — `/entries?month=2026-09&category=dining` —\n    // so they survive a reload, a shared link and the back button.\n    derived month = query.month ?? \"\"\n    derived category = query.category ?? \"\"\n    derived shown = Ledger.newestFirst.filter(e => (month == \"\" || e.date.slice(0, 7) == month) && (category == \"\" || e.category == category))",title:"wf"});_e6218.appendChild(_e6404);const _e6405=WF.el("div",{className:"wf-markdown",markdown:"Choosing a month calls `navigate(\"/entries?month=…\")`. The address changes, `query` follows it, and so does the list.\n\nAn entry also has a page of its own at `/entries/:id`, where `id` is a typed parameter. The page looks the entry up with `Ledger.entries.find(…)` and draws it inside `if let e = entry`. `if let` binds the value only when it is there, which the checker requires before the page reads its fields ([Pages and routing](/docs/guide/pages-and-routing)).\n\n**Check it:** on `/entries`, pick a month. The address gains `?month=…` and the list narrows. Press the browser's back button: the filter goes."});_e6218.appendChild(_e6405);const _e6406=WF.el("h3",{className:"wf-heading",id:"step-8-use-one-form-for-new-and-for-edit"},"Step 8: Use one form for new and for edit");_e6218.appendChild(_e6406);const _e6407=WF.el("div",{className:"wf-markdown",markdown:"`EntryForm` adds an entry or, given one, changes it:"});_e6218.appendChild(_e6407);const _e6408=Component_CodeBlock({code:"// src/components/EntryForm.wf\n/// The form for a new entry — or, given one, for changing it. It checks what\n/// the reader typed, writes it to the ledger, and says so with `saved`.\ncomponent EntryForm(entry: Entry? = null) {\n    use Ledger\n    event saved()\n\n    state kind: Kind = entry?.kind ?? .expense\n    state amount: Number? = if let e = entry { e.amount.amount / 100 } else { null }\n    state date: Date? = entry?.date ?? Ledger.today\n    state category = entry?.category ?? \"groceries\"\n    state note = entry?.note ?? \"\"\n\n    validate amount {\n        required\n        min(0.01)\n    }\n    // Not in the future. With no message of its own, the rule shows the\n    // translation of `form.max`; `Ledger.today` is read each time it checks.\n    validate date {\n        required\n        max(Ledger.today)\n    }\n    validate note { maxLength(60) }",title:"wf"});_e6218.appendChild(_e6408);const _e6409=WF.el("div",{className:"wf-markdown",markdown:"- A `validate` block sits beside the state it guards. The control bound to that state shows what the rules say — the message, `aria-invalid` and the link between them — with nothing more written ([Forms](/docs/guide/forms)).\n- A rule with no message of its own shows the translation of `form.<rule>`, so `en.json` and `ar.json` each say \"that date has not happened yet\" once.\n- The form says it is done with an event, `saved`. The caller decides what that means: close the dialog, or go back to the entry.\n\nThe submit button follows the form:"});_e6218.appendChild(_e6409);const _e6410=Component_CodeBlock({code:"// src/components/EntryForm.wf\n        Row(justify: .end, gap: .sm) {\n            Button(if entry != null { t(\"action.save\") } else { t(\"action.add\") }, type: .submit, disabled: !form.valid).primary\n        }",title:"wf"});_e6218.appendChild(_e6410);const _e6411=WF.el("div",{className:"wf-markdown",markdown:"`Form(bind: form)` hands the component a handle on the form. `form.valid` is whether every rule holds, and the button follows it as the reader types.\n\n**Check it:** in the new-entry dialog, type `0` as the amount and leave the field: it says *Enter an amount above zero*, and **Add entry** stays disabled. Type `12.50`, and the button turns on."});_e6218.appendChild(_e6411);const _e6412=WF.el("h3",{className:"wf-heading",id:"step-9-add-a-dialog-and-a-shortcut"},"Step 9: Add a dialog and a shortcut");_e6218.appendChild(_e6412);const _e6413=WF.el("div",{className:"wf-markdown",markdown:"The app listens for two keys at the top of `src/App.wf`:"});_e6218.appendChild(_e6413);const _e6414=Component_CodeBlock({code:"// src/App.wf\n    // `n` opens a new entry from anywhere. A key with no modifier is left to\n    // the field the reader is typing in, so an `n` in a note is just a letter.\n    on key(\"n\") { Ui.compose() }\n    on key(\"Escape\") { Ui.closeAll() }",title:"wf"});_e6218.appendChild(_e6414);const _e6415=WF.el("div",{className:"wf-markdown",markdown:"`on key` at the top of the app listens on the document for as long as the page shows ([Events](/docs/guide/events)). The dialog is a `Modal` whose `title:` is its accessible name. It keeps focus inside while it is open, and Escape closes it:"});_e6218.appendChild(_e6415);const _e6416=Component_CodeBlock({code:"// src/App.wf\n    Modal(visible: Ui.composing, title: t(\"compose.title\")) {\n        if Ui.composing {\n            EntryForm {\n                on saved {\n                    Ui.composing = false\n                    Ui.notify(t(\"toast.added\"))\n                }\n            }\n        }\n    }",title:"wf"});_e6218.appendChild(_e6416);const _e6417=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** press `n` anywhere outside a field, and the new-entry dialog opens with focus inside it. Press Escape, and it closes. Add an entry, and the dialog closes and a notice says it was added."});_e6218.appendChild(_e6417);const _e6418=WF.el("h3",{className:"wf-heading",id:"step-10-speak-two-languages"},"Step 10: Speak two languages");_e6218.appendChild(_e6418);const _e6419=WF.el("div",{className:"wf-markdown",markdown:"Every word on screen is `t(\"key\")`, read from `src/translations/en.json` or `ar.json`. A message with plural forms is several keys:"});_e6218.appendChild(_e6419);const _e6420=Component_CodeBlock({code:"{\n  \"entries.zero\": \"No entries\",\n  \"entries.one\": \"{count} entry\",\n  \"entries.other\": \"{count} entries\"\n}",title:"json"});_e6218.appendChild(_e6420);const _e6421=WF.el("div",{className:"wf-markdown",markdown:"- `t(\"entries\", { count: n })` picks the form the language's rules call for. English needs two forms and a zero; Arabic has six ([Internationalization](/docs/guide/i18n)).\n- Switching to Arabic sets `dir=\"rtl\"` on the page, and the sidebar, the rows and the grids mirror themselves.\n- `format(m)` and dates follow the language too.\n- The reader's choice is a `persist` in a small `Prefs` store, and an `effect` in the app shell applies it on every visit.\n\n**Check it:** on **Settings**, choose Arabic. The page reads right to left, and every label is in Arabic. Reload: it stays in Arabic.\n\nIf a key shows on screen instead of its words, it is missing from a translation file; `wf check` reports it as `I01`, and `wf translations` lists what each locale lacks."});_e6218.appendChild(_e6421);const _e6422=WF.el("h3",{className:"wf-heading",id:"step-11-export-and-import-the-data"},"Step 11: Export and import the data");_e6218.appendChild(_e6422);const _e6423=WF.el("div",{className:"wf-markdown",markdown:"The Settings page writes the ledger out as a CSV file:"});_e6218.appendChild(_e6423);const _e6424=Component_CodeBlock({code:"// src/pages/Settings.wf\n    action exportCsv() {\n        let lines = Ledger.newestFirst.map(e => csvLine(e))\n        saveTextFile(\"pocket-{Ledger.today}.csv\", [CSV_HEADER, ...lines].join(\"\\n\"), \"text/csv\")\n    }",title:"wf"});_e6218.appendChild(_e6424);const _e6425=WF.el("div",{className:"wf-markdown",markdown:"`saveTextFile` is not WebFluent. It is a function in `src/files.js`, a plain browser script that the build links on every page. Its JSDoc types the call, so `saveTextFile(1)` is an error where it is written ([JavaScript interop](/docs/guide/interop)).\n\nImporting reads a file from a `FileUpload` with `await f.text()`, parses each line and merges what is new. Then it tells every other open tab:"});_e6218.appendChild(_e6425);const _e6426=Component_CodeBlock({code:"// src/pages/Settings.wf\n        let added = Ledger.merge(parsed)\n        news.post({ count: added })",title:"wf"});_e6218.appendChild(_e6426);const _e6427=WF.el("div",{className:"wf-markdown",markdown:"`news` is `channel news = broadcast(\"pocket\")`, a channel every tab of the site hears. The app shell listens on it and shows a notice ([Realtime](/docs/guide/realtime)). The ledger itself needs no channel: `persist` already keeps every tab in step.\n\n**Check it:** on **Settings**, export the ledger, and the browser saves `pocket-<today's date>.csv`. Open a second tab, import the file in the first: the second tab shows a notice of how many entries were added."});_e6218.appendChild(_e6427);const _e6428=WF.el("h3",{className:"wf-heading",id:"step-12-test-it-and-run-the-checks"},"Step 12: Test it, and run the checks");_e6218.appendChild(_e6428);const _e6429=WF.el("div",{className:"wf-markdown",markdown:"A test drives the real form by the labels a reader sees — the English ones, since a test reads the project's default locale ([Testing](/docs/guide/testing)):"});_e6218.appendChild(_e6429);const _e6430=Component_CodeBlock({code:"// tests/pocket.wf\ntest \"an entry added through the form moves the balance\" {\n    use Ledger\n    Text(\"Balance {format(Ledger.balance)}\")\n    EntryForm\n\n    expect \"Balance $16,533.56\"\n    click \"Money in\"\n    type \"250\" into \"Amount\"\n    click \"Add entry\"\n    expect \"Balance $16,783.56\"",title:"wf"});_e6218.appendChild(_e6430);const _e6431=WF.el("div",{className:"wf-markdown",markdown:"Pocket has eight tests: the cards and rows draw what they should, a blank amount is refused, `n` opens the dialog and Escape closes it, and removing an entry takes it out of every total. Run them and the checks:"});_e6218.appendChild(_e6431);const _e6432=Component_Terminal({lines:[({command:"wf test",output:""}),({command:"wf check --deny-warnings",output:""}),({command:"wf build",output:""}),({command:"wf verify",output:""})]});_e6218.appendChild(_e6432);const _e6433=WF.el("div",{className:"wf-markdown",markdown:"**Check it:** `wf test` reports `8 passed`, and `wf verify` ends with `0 problem(s)`. `build/` is a single-page app with a service worker, `sw.js`, beside it. Put it on a host that answers every path with `index.html` ([Deploying](/docs/guide/deploying)), and the second visit works with no network."});_e6218.appendChild(_e6433);const _e6434=WF.el("h3",{className:"wf-heading",id:"what-you-built-in-pocket"},"What you built in Pocket");_e6218.appendChild(_e6434);const _e6435=WF.el("div",{className:"wf-markdown",markdown:"- A ledger typed with `Money`, `Date`, `Color` and `Uuid` ([Types](/docs/guide/types)).\n- Totals that are all `derived` values of one store, and a `persist` migration that keeps returning readers' data ([Stores](/docs/guide/stores)).\n- A shell that changes with the window, and responsive grids ([Styling](/docs/guide/styling)).\n- A form that validates itself, a dialog and keyboard shortcuts ([Forms](/docs/guide/forms), [Events](/docs/guide/events)).\n- Two languages, plural forms and right-to-left layout ([Internationalization](/docs/guide/i18n)).\n- A script of your own, and a channel between tabs ([JavaScript interop](/docs/guide/interop), [Realtime](/docs/guide/realtime)).\n- A site that works offline ([Offline](/docs/guide/offline))."});_e6218.appendChild(_e6435);const _e6436=WF.el("h2",{className:"wf-heading",id:"recipes"},"Recipes");_e6218.appendChild(_e6436);const _e6437=WF.el("div",{className:"wf-markdown",markdown:"These are smaller pieces that most projects need. Each is a whole page you can build and adapt."});_e6218.appendChild(_e6437);const _e6438=WF.el("h3",{className:"wf-heading",id:"debounce-a-search"},"Debounce a search");_e6218.appendChild(_e6438);const _e6439=WF.el("div",{className:"wf-markdown",markdown:"To wait until the reader stops typing before you search, keep what they typed apart from what you search for:"});_e6218.appendChild(_e6439);const _e6440=Component_CodeBlock({code:"page Search(path: \"/\", title: \"Search\", description: \"Search as you type, without a request per key.\") {\n    state typed = \"\"\n    state q = \"\"\n    action commit(value: String) { if value == typed { q = value } }\n    effect {\n        let pending = typed\n        setTimeout(() => commit(pending), 300)\n    }\n    resource hits = fetch(\"/api/search?q={q}\")\n    Heading(\"Search\").h1\n    Input(bind: typed, placeholder: \"Search\", aria-label: \"Search\")\n    match hits {\n        loading { Spinner.sm }\n        error(e) { Text(e.message).danger }\n        ready(list) { Text(\"{list.length} results for {q}\") }\n    }\n}",title:"wf"});_e6218.appendChild(_e6440);const _e6441=WF.el("div",{className:"wf-markdown",markdown:"The effect runs again on every keystroke, and each run schedules a check. Only the check whose value is still current writes `q`, and the resource follows `q`. The timer is the browser's `setTimeout`, because `after(ms)` is a declaration with a body, not a statement an effect can hold."});_e6218.appendChild(_e6441);const _e6442=WF.el("h3",{className:"wf-heading",id:"page-through-results"},"Page through results");_e6218.appendChild(_e6442);const _e6443=WF.el("div",{className:"wf-markdown",markdown:"To show a long list a page at a time, keep the page number in state and splice it into the address:"});_e6218.appendChild(_e6443);const _e6444=Component_CodeBlock({code:"page Rows(path: \"/\", title: \"Rows\", description: \"Every row, twenty at a time.\") {\n    state page = 1\n    state perPage = 20\n    resource rows = fetch(\"/api/rows?page={page}&per={perPage}\")\n    Heading(\"Rows\").h1\n    match rows {\n        loading { Spinner }\n        error(e) { Text(e.message).danger }\n        ready(r) {\n            for row in r.items by row.id { Text(row.name) }\n            Row(gap: .sm, align: .center) {\n                Button(\"Previous\", disabled: page == 1) { on click { page = page - 1 } }\n                Text(\"Page {page} of {r.pages}\")\n                Button(\"Next\", disabled: page >= r.pages) { on click { page = page + 1 } }\n            }\n        }\n    }\n}",title:"wf"});_e6218.appendChild(_e6444);const _e6445=WF.el("div",{className:"wf-markdown",markdown:"A change of `page` changes the address, so the resource asks again."});_e6218.appendChild(_e6445);const _e6446=WF.el("h3",{className:"wf-heading",id:"update-at-once-and-roll-back-on-failure"},"Update at once, and roll back on failure");_e6218.appendChild(_e6446);const _e6447=WF.el("div",{className:"wf-markdown",markdown:"To show a change before the server agrees, keep the old value and put it back if the request fails:"});_e6218.appendChild(_e6447);const _e6448=Component_CodeBlock({code:"type Item { id: String, liked: Bool }\n\npage Likes(path: \"/\", title: \"Likes\", description: \"A like that shows at once.\") {\n    state items: [Item] = [Item(id: \"a\", liked: false)]\n    state error = \"\"\n    action like(id: String) {\n        let before = items\n        items = items.map(i => if i.id == id { Item(id: i.id, liked: !i.liked) } else { i })\n        try {\n            await fetch(\"/api/like/{id}\", { method: \"POST\" })\n        } catch e {\n            items = before\n            error = \"Could not save. Try again.\"\n        }\n    }\n    Heading(\"Likes\").h1\n    for i in items by i.id {\n        Button(if i.liked { \"♥\" } else { \"♡\" }, aria-label: \"Like\").sm { on click { like(i.id) } }\n    }\n    if error != \"\" { Toast(error).danger }\n}",title:"wf"});_e6218.appendChild(_e6448);const _e6449=WF.el("div",{className:"wf-markdown",markdown:"`optimistic(holder, change)` does the same with less code inside an action; see [Data](/docs/guide/data#show-a-change-before-the-server-agrees)."});_e6218.appendChild(_e6449);const _e6450=WF.el("h3",{className:"wf-heading",id:"build-a-confirm-dialog-component"},"Build a confirm dialog component");_e6218.appendChild(_e6450);const _e6451=WF.el("div",{className:"wf-markdown",markdown:"To ask before a destructive action, wrap a `Dialog` in a component that fires `confirm` or `cancel`:"});_e6218.appendChild(_e6451);const _e6452=Component_CodeBlock({code:"component Confirm(_ title: String, visible: Bool, danger: Bool = false) {\n    event confirm()\n    event cancel()\n    slot\n    Dialog(visible: visible, title: title) {\n        children\n        Row(gap: .sm, justify: .end) {\n            Button(\"Cancel\") { on click { emit cancel() } }\n            Button(\"Confirm\", tone: if danger { .danger } else { .primary }) { on click { emit confirm() } }\n        }\n    }\n}\n\npage Account(path: \"/\", title: \"Account\", description: \"Close your account.\") {\n    state asking = false\n    state gone = false\n    Heading(\"Account\").h1\n    Button(\"Delete account\").danger { on click { asking = true } }\n    Confirm(\"Delete your account?\", visible: asking, danger: true) {\n        on confirm { gone = true  asking = false }\n        on cancel { asking = false }\n        Text(\"Everything goes. This cannot be undone.\")\n    }\n    if gone { Alert(\"Account deleted.\").info }\n}",title:"wf"});_e6218.appendChild(_e6452);const _e6453=WF.el("div",{className:"wf-markdown",markdown:"The caller's block fills the default slot, so the question's detail is the caller's to write."});_e6218.appendChild(_e6453);const _e6454=WF.el("h3",{className:"wf-heading",id:"make-navigation-responsive"},"Make navigation responsive");_e6218.appendChild(_e6454);const _e6455=WF.el("div",{className:"wf-markdown",markdown:"To show links on a wide screen and a menu button on a narrow one, branch on `viewport`:"});_e6218.appendChild(_e6455);const _e6456=Component_CodeBlock({code:"page Nav(path: \"/\", title: \"Home\", description: \"Navigation that fits the screen.\") {\n    state open = false\n    Heading(\"Home\").h1\n    if viewport.md {\n        Row(gap: .md) {\n            Link(\"Home\", to: \"/\")\n            Link(\"Docs\", to: \"/docs\")\n            Link(\"Pricing\", to: \"/pricing\")\n        }\n    } else {\n        IconButton(icon: \"menu\", label: \"Open navigation\") { on click { open = !open } }\n        show open {\n            Stack(gap: .sm, animate: .slideDown) {\n                Link(\"Home\", to: \"/\")\n                Link(\"Docs\", to: \"/docs\")\n                Link(\"Pricing\", to: \"/pricing\")\n            }\n        }\n    }\n}",title:"wf"});_e6218.appendChild(_e6456);const _e6457=WF.el("h3",{className:"wf-heading",id:"show-validation-messages-on-a-form"},"Show validation messages on a form");_e6218.appendChild(_e6457);const _e6458=WF.el("div",{className:"wf-markdown",markdown:"To check a form as the reader fills it in, put a `validate` block beside each state:"});_e6218.appendChild(_e6458);const _e6459=Component_CodeBlock({code:"page Signup(path: \"/\", title: \"Sign up\", description: \"Make an account.\") {\n    state email = \"\"\n    state password = \"\"\n    state confirm = \"\"\n    state sent = false\n    validate email { required  email \"Enter a valid email\" }\n    validate password { required  minLength(8) \"At least 8 characters\" }\n    validate confirm { matches(password) \"The passwords differ\" }\n    Heading(\"Sign up\").h1\n    Form(bind: form) {\n        on submit { sent = true  form.reset() }\n        Input(bind: email, name: \"email\", label: \"Email\").email\n        Input(bind: password, name: \"password\", label: \"Password\").password\n        Input(bind: confirm, name: \"confirm\", label: \"Confirm password\").password\n        Button(\"Create account\", type: .submit, disabled: !form.valid).primary\n    }\n    if sent { Alert(\"Welcome aboard.\").success }\n}",title:"wf"});_e6218.appendChild(_e6459);const _e6460=WF.el("div",{className:"wf-markdown",markdown:"Each control shows its own message when the reader leaves it, and a submit that fails moves focus to the first problem. [Forms](/docs/guide/forms) lists every rule."});_e6218.appendChild(_e6460);const _e6461=WF.el("h3",{className:"wf-heading",id:"keep-the-active-tab-in-the-address"},"Keep the active tab in the address");_e6218.appendChild(_e6461);const _e6462=WF.el("div",{className:"wf-markdown",markdown:"To make a tab survive a reload, read it from `hash`:"});_e6218.appendChild(_e6462);const _e6463=Component_CodeBlock({code:"page Account(path: \"/account\", title: \"Account\", description: \"Your profile and billing.\") {\n    derived tab = if hash != \"\" { hash } else { \"profile\" }\n    Heading(\"Account\").h1\n    Row(gap: .sm) {\n        Link(\"Profile\", to: \"/account#profile\")\n        Link(\"Billing\", to: \"/account#billing\")\n    }\n    if tab == \"profile\" { Text(\"Profile settings\") }\n    if tab == \"billing\" { Text(\"Billing settings\") }\n}",title:"wf"});_e6218.appendChild(_e6463);const _e6464=WF.el("h3",{className:"wf-heading",id:"pass-a-store-s-value-to-a-component-as-a-prop"},"Pass a store's value to a component as a prop");_e6218.appendChild(_e6464);const _e6465=WF.el("div",{className:"wf-markdown",markdown:"A component that needs only one value from a store can take it as a prop instead of using the store. That keeps the component reusable outside that store:"});_e6218.appendChild(_e6465);const _e6466=Component_CodeBlock({code:"store Cart { state count = 0 }\n\ncomponent CartBadge(count: Number) {\n    if count > 0 { Badge(\"{count}\").primary }\n}\n\npage Shop(path: \"/\", title: \"Shop\", description: \"Everything we sell.\") {\n    use Cart\n    Heading(\"Shop\").h1\n    CartBadge(count: Cart.count)\n}",title:"wf"});_e6218.appendChild(_e6466);const _e6467=WF.el("h3",{className:"wf-heading",id:"count-down"},"Count down");_e6218.appendChild(_e6467);const _e6468=WF.el("div",{className:"wf-markdown",markdown:"To count down once a second, change a state in an `every` timer:"});_e6218.appendChild(_e6468);const _e6469=Component_CodeBlock({code:"page Countdown(path: \"/\", title: \"Countdown\", description: \"Ten seconds, counted down.\") {\n    state left = 10\n    every(1000) { if left > 0 { left = left - 1 } }\n    Heading(\"Countdown\").h1\n    Progress(value: 10 - left, max: 10)\n    Text(if left == 0 { \"Done\" } else { \"{left}s\" })\n}",title:"wf"});_e6218.appendChild(_e6469);const _e6470=WF.el("div",{className:"wf-markdown",markdown:"The timer stops when the page leaves."});_e6218.appendChild(_e6470);const _e6471=WF.el("h3",{className:"wf-heading",id:"sign-in-with-a-session-cookie"},"Sign in with a session cookie");_e6218.appendChild(_e6471);const _e6472=WF.el("div",{className:"wf-markdown",markdown:"To sign a reader in without holding a token in the page, describe the service with `credentials: .sameOrigin` and keep the user in a store:"});_e6218.appendChild(_e6472);const _e6473=Component_CodeBlock({code:"type User { id: String, name: String }\n\napi Auth(base: \"/api\") {\n    credentials: .sameOrigin\n    get me() -> User\n    post signIn(body: Map) -> User\n        errors { 401 -> Map }\n    post signOut()\n}\n\nstore Session {\n    state user: User? = null\n    state checked = false\n    derived signedIn = user != null\n    action load() {\n        try { user = await Auth.me() } catch e { user = null }\n        checked = true\n    }\n    action signIn(email: String, password: String) {\n        user = await Auth.signIn(body: { email: email, password: password })\n        navigate(\"/account\")\n    }\n    action signOut() {\n        await Auth.signOut()\n        user = null\n        navigate(\"/\")\n    }\n}\n\npage SignIn(path: \"/sign-in\", title: \"Sign in\", description: \"Sign in to your account.\", noindex: true) {\n    state email = \"\"\n    state password = \"\"\n    state problem = \"\"\n    validate email { required  email }\n    validate password { required }\n    action send() {\n        problem = \"\"\n        try { await Session.signIn(email, password) } catch e { problem = \"That email and password do not match.\" }\n    }\n    Heading(\"Sign in\").h1\n    if problem != \"\" { Alert(problem).danger }\n    Form(bind: form) {\n        on submit { send() }\n        Input(bind: email, label: \"Email\").email\n        Input(bind: password, label: \"Password\").password\n        Button(\"Sign in\", type: .submit, disabled: send.pending).primary\n    }\n}\n\npage Account(path: \"/account\", title: \"Your account\", description: \"Your account.\", guard: Session.signedIn, redirect: \"/sign-in\") {\n    use Session\n    Heading(\"Your account\").h1\n    if let u = Session.user { Text(\"Signed in as {u.name}\") }\n    Button(\"Sign out\") { on click { Session.signOut() } }\n}",title:"wf"});_e6218.appendChild(_e6473);const _e6474=WF.el("div",{className:"wf-markdown",markdown:"The session is an httpOnly cookie the server sets, so the page never holds a token. `guard:` hides the page from a reader who is signed out, and the server still checks every request ([Security](/docs/guide/security#keep-the-session-in-a-cookie)). Call `Session.load()` from the app's set-up, so a returning reader is signed in."});_e6218.appendChild(_e6474);const _e6475=WF.el("h3",{className:"wf-heading",id:"load-more"},"Load more");_e6218.appendChild(_e6475);const _e6476=WF.el("div",{className:"wf-markdown",markdown:"To add the next page of results below the ones shown, call an endpoint with `paginate: .page`:"});_e6218.appendChild(_e6476);const _e6477=Component_CodeBlock({code:"type Item { id: String, name: String }\n\napi Catalog(base: \"/api\") {\n    get items(page: Number = 1) -> [Item]\n}\n\npage Items(path: \"/items\", title: \"Items\", description: \"Everything, a page at a time.\") {\n    state page = 1\n    resource list = Catalog.items(page: page, paginate: .page)\n    Heading(\"Items\").h1\n    for item in list.items by item.id { Text(item.name) }\n    if list.hasMore {\n        Button(\"Load more\", disabled: list.state == \"loading\") { on click { list.loadMore() } }\n    }\n}",title:"wf"});_e6218.appendChild(_e6477);const _e6478=WF.el("div",{className:"wf-markdown",markdown:"`list.items` is every item loaded so far, and `list.loadMore()` asks for the next page."});_e6218.appendChild(_e6478);const _e6479=WF.el("h3",{className:"wf-heading",id:"keep-filters-in-the-address"},"Keep filters in the address");_e6218.appendChild(_e6479);const _e6480=WF.el("div",{className:"wf-markdown",markdown:"To make a filter survive a reload, a shared link and the back button, read it from `query` instead of holding it in a `state`:"});_e6218.appendChild(_e6480);const _e6481=Component_CodeBlock({code:"page Products(path: \"/products\", title: \"Products\", description: \"Everything we sell.\") {\n    derived sort = query.sort ?? \"name\"\n    Heading(\"Products\").h1\n    Row(gap: .sm) {\n        Link(\"By name\", to: \"/products?sort=name\")\n        Link(\"By price\", to: \"/products?sort=price\")\n    }\n    Text(\"Sorted by {sort}\")\n}",title:"wf"});_e6218.appendChild(_e6481);const _e6482=WF.el("h3",{className:"wf-heading",id:"add-a-dark-mode-switch"},"Add a dark-mode switch");_e6218.appendChild(_e6482);const _e6483=WF.el("div",{className:"wf-markdown",markdown:"To let the reader pick light, dark or the system's choice, call `setTheme` and read `theme`:"});_e6218.appendChild(_e6483);const _e6484=Component_CodeBlock({code:"page Settings(path: \"/settings\", title: \"Settings\", description: \"How the site looks.\") {\n    Heading(\"Settings\").h1\n    Row(gap: .sm) {\n        Button(\"Light\", outlined: theme != \"light\") { on click { setTheme(\"light\") } }\n        Button(\"Dark\", outlined: theme != \"dark\") { on click { setTheme(\"dark\") } }\n        Button(\"Match the system\", outlined: theme != \"system\") { on click { setTheme(\"system\") } }\n    }\n}",title:"wf"});_e6218.appendChild(_e6484);const _e6485=WF.el("div",{className:"wf-markdown",markdown:"The switch needs a dark theme named in the config ([Styling](/docs/guide/styling#dark-mode))."});_e6218.appendChild(_e6485);const _e6486=WF.el("h3",{className:"wf-heading",id:"copy-to-the-clipboard"},"Copy to the clipboard");_e6218.appendChild(_e6486);const _e6487=WF.el("div",{className:"wf-markdown",markdown:"To copy text, call the browser's clipboard from an action:"});_e6218.appendChild(_e6487);const _e6488=Component_CodeBlock({code:"page Share(path: \"/share\", title: \"Share\", description: \"Copy the link.\") {\n    state copied = false\n    action copy(text: String) {\n        await navigator.clipboard.writeText(text)\n        copied = true\n    }\n    Heading(\"Share\").h1\n    Button(\"Copy the link\") { on click { copy(location.href) } }\n    if copied { Toast(\"Copied\").success }\n}",title:"wf"});_e6218.appendChild(_e6488);const _e6489=WF.el("h3",{className:"wf-heading",id:"draw-a-chart-from-a-library"},"Draw a chart from a library");_e6218.appendChild(_e6489);const _e6490=WF.el("div",{className:"wf-markdown",markdown:"To use a charting library, list its URL in `meta.scripts`, call it from a script of your own, and hand it a canvas with `Host`. The full example is in [JavaScript interop](/docs/guide/interop#load-a-library-from-a-cdn)."});_e6218.appendChild(_e6490);const _e6491=WF.el("h2",{className:"wf-heading",id:"where-to-go-next"},"Where to go next");_e6218.appendChild(_e6491);const _e6492=WF.el("div",{className:"wf-markdown",markdown:"- The [components reference](/docs/reference), for every prop and flag.\n- `examples/` in the repository: the tutorials, reference PDFs and slide decks, and the `tests/fixtures/` projects — a gallery, a dashboard, a docs site, an offline site — each complete.\n- `wf docs` in your own project, for what *your* components take."});_e6218.appendChild(_e6492);_root.appendChild(_e6218);return _root;}
WF.page("TutorialsGuide",Page_TutorialsGuide);